SELECT ?zone ?zoneName ?ahu ?ahuName WHERE {
  ?ahu brick:hasTag "AHU03" .
  ?ahu a brick:AirHandlingUnit .
  ?ahu brick:hasSubsection* ?zone .
  ?zone a brick:Zone .
  OPTIONAL { ?ahu rdfs:label ?ahuName }
  OPTIONAL { ?zone rdfs:label ?zoneName }
}

SELECT ?ahu ?ahuName WHERE {
  ?ahu a brick:AirHandlingUnit .
  OPTIONAL { ?ahu rdfs:label ?ahuName }
}

SELECT ?cls (COUNT(?s) AS ?n) WHERE {
  ?s a ?cls .
} GROUP BY ?cls

SELECT ?ahu ?ahuName ?vav ?vavName WHERE {
  ?ahu a brick:AHU .
  OPTIONAL { ?ahu brick:hasTag ?t }
  OPTIONAL { ?ahu rdfs:label ?ahuName }
  ?ahu brick:hasSubsection* ?vav .
  ?vav a brick:VAV .
  OPTIONAL { ?vav rdfs:label ?vavName }
}

SELECT ?vav ?p ?o WHERE {
  ?vav a brick:VAV .
  ?vav ?p ?o .
  FILTER (STRSTARTS(STR(?vav), "http://buildgraph.org/BG_large_office_2004_0000#VAV_F4"))
} LIMIT 200

SELECT ?sensor ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?sensor ref:hasTimeseriesId ?tsid .
  FILTER (STRSTARTS(STR(?sensor), "http://buildgraph.org/BG_large_office_2004_0000#VAV_F4"))
}

